#include <stddef.h>

void compress_string(const char *src, char *dest)
{
    if (!src || !dest)
        return;

    const char *run_start = src;

    while (*run_start) {
        const char *run_end = run_start;
        char current_char = *run_start;

        /* Find the end of the current run */
        while (*run_end && *run_end == current_char) {
            run_end++;
        }

        /* Write the character */
        *dest++ = current_char;

        /* Calculate and write the count */
        size_t count = (size_t)(run_end - run_start);

        if (count >= 10000) {
            *dest++ = (char)('0' + count / 10000 % 10);
            *dest++ = (char)('0' + count / 1000  % 10);
        } else if (count >= 1000) {
            *dest++ = (char)('0' + count / 1000 % 10);
        } else if (count >= 100) {
            *dest++ = (char)('0' + count / 100 % 10);
        } else if (count >= 10) {
            *dest++ = (char)('0' + count / 10 % 10);
        }

        /* Write last digit */
        *dest++ = (char)('0' + count % 10);

        /* Move to the next run */
        run_start = run_end;
    }

    *dest = '\0';
}

#include <stddef.h>

void compress_string(const char *src, char *dest)
{
    if (!src || !dest)
        return;

    const char *run_start = src;

    while (*run_start) {
        char current_char = *run_start;
        const char *run_end = run_start + 1;

        /* Find the end of the current run */
        while (*run_end && *run_end == current_char) {
            run_end++;
        }

        /* Write the character */
        *dest++ = current_char;

        /* Calculate count and write digits */
        int count = (int)(run_end - run_start);
        int div = 1;
        while (count / (div * 10)) {
            div *= 10;
        }
        while (div) {
            *dest++ = '0' + count / div;
            div /= 10;
        }

        /* Move to the next run */
        run_start = run_end;
    }

    *dest = '\0';
}
